"""Replace the Z-Anatomy kidney overlay (uncertain non-commercial origin, and drawn on top of the BodyParts3D
kidneys) with HuBMAP scan-derived renal pelvis/calyces and renal medulla plus generated intrarenal vessels."""
import glob,sys
mf=glob.glob('assets/assetManifest-*.js')[0];s=open(mf).read()
i=s.index('{id:`zanatomy-kidney`');j=s.index('},{id:',i+10)+1
A='''{id:`hubmap-kidney`,name:`Renal pelvis, calyces and renal medulla (HuBMAP Visible Human)`,kind:`gltf`,url:`./models/hubmap-kidney.glb`,fidelity:`anatomical`,license:`CC BY 4.0 \\u2014 HuBMAP CCF 3D Reference Object Library`,attribution:`HuBMAP Consortium, CCF 3D Reference Object Library, Visible Human male kidneys (left https://doi.org/10.48539/HBM562.JGPS.244, right https://doi.org/10.48539/HBM272.ZVPQ.979 Kristen Browne and Heidi Schlehlein), CC BY 4.0. Modified: the renal pelvis with major and minor calyces, and the renal pyramids with papillae, were merged, simplified and fitted with one similarity transform per side to the kidneys shown in the app (BodyParts3D). Fit of kidney surfaces: median 3.6 mm left, 4.5 mm right. Not expert-validated.`,description:`Scan-derived renal pelvis with calyces and renal medulla (pyramids), placed inside each kidney.`,objectMap:{"hk_renal_pelvis_l": "renal-pelvis-left", "hk_renal_pelvis_r": "renal-pelvis-right", "hk_renal_medulla_l": "renal-medulla-left", "hk_renal_medulla_r": "renal-medulla-right"}},{id:`anatomyverse-renal-vessels`,name:`Intrarenal vessels (generated diagram)`,kind:`gltf`,url:`./models/anatomyverse-renal-vessels.glb`,fidelity:`schematic`,license:`Original generated geometry \\u2014 3D Anatomy`,attribution:`Generated tubes (not a scan): anterior and posterior divisions of the renal artery, interlobar arteries and veins routed between the scan-derived renal pyramids. An approximation for teaching the branching pattern; pending expert review.`,description:`Diagram of the segmental and interlobar vessels inside each kidney.`,objectMap:{"gv_segart_ant_l": "anterior-branch-of-renal-artery", "gv_segart_ant_r": "anterior-branch-of-renal-artery", "gv_segart_post_l": "posterior-branch-of-renal-artery", "gv_segart_post_r": "posterior-branch-of-renal-artery", "gv_intrarenal_art_l": "intrarenal-arteries", "gv_intrarenal_art_r": "intrarenal-arteries", "gv_intrarenal_vein_l": "intrarenal-veins", "gv_intrarenal_vein_r": "intrarenal-veins"}}'''
s=s[:i]+A+s[j:]
o='{assetId:`zanatomy-kidney`,gate:`ld_org`,replacesParts:[`kidney_L`,`kidney_R`,`ureter_L`,`ureter_R`,`adrenal_gland_L`,`adrenal_gland_R`]}'
assert s.count(o)==1;s=s.replace(o,'{assetId:`hubmap-kidney`,gate:`ld_org`,replacesParts:[]},{assetId:`anatomyverse-renal-vessels`,gate:`ld_org`,replacesParts:[]}')
k=s.index('{id:`renal-pelvis-right`');e=s.index('reviewStatus:`reviewed`}',k)+len('reviewStatus:`reviewed`}')
com='bloodSupply:`Interlobar and arcuate arteries (branches of the segmental arteries); vasa recta supply the medulla.`,venousDrainage:`Arcuate and interlobar veins to the renal vein.`,innervation:`Renal plexus (sympathetic T10-L1).`,'
R=',{id:`renal-medulla`,'+com+'name:`Renal medulla`,latinName:`Medulla renalis`,synonyms:[`Renal pyramids`],system:`urinary`,region:`abdomen`,layer:`organs`,parentId:`kidney`,location:`Inner part of the kidney, deep to the cortex, arranged as renal pyramids whose apices (papillae) point into the minor calyces.`,description:`The medulla consists of about 8 to 18 conical renal pyramids separated by renal columns of cortex. It contains the loops of Henle, collecting ducts and vasa recta, which concentrate the urine. Each papilla drains into a minor calyx.`,clinicalRelevance:`Renal papillary necrosis occurs in diabetes, analgesic abuse, sickle cell disease and severe pyelonephritis. The medulla is relatively hypoxic and is vulnerable in acute tubular injury.`,sources:[],reviewStatus:`pending-expert-review`}'
for sd,S in(('left','Left'),('right','Right')):
    R+=',{id:`renal-medulla-%s`,'%sd+com+'name:`%s renal medulla`,synonyms:[],system:`urinary`,region:`abdomen`,layer:`organs`,parentId:`renal-medulla`,side:`%s`,location:`%s side of the body.`,description:`The %s renal medulla (renal pyramids). Its structure, function and clinical notes are given under Renal medulla.`,sources:[],reviewStatus:`pending-expert-review`}'%(S,sd,S,sd)
assert "id:`renal-medulla`" not in s;s=s[:e]+R+s[e:]
open(mf,'w').write(s)
vf=glob.glob('assets/AnatomyViewer-*.js')[0];v=open(vf).read()
f=".filter(_p=>!(e.id===`zanatomy-kidney`&&/^(kidney|adrenal-gland|ureter)-(left|right)$/.test(_p.structureId??``)))"
assert v.count(f)==1;v=v.replace(f,'');assert 'zanatomy-kidney' not in v;open(vf,'w').write(v)
